import { expect } from '@playwright/test';
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { test } from './helpers/archivebox';
import { launchExtension, readSnapshots, waitForSavedSettings } from './helpers/extension';

test('a discarded tab preserves saved browser storage without blocking persona sync', async ({ archivebox }) => {
  const document = await readFile(new URL('./fixtures/auto-archive.html', import.meta.url));
  const source = createServer((_request, response) => {
    response.writeHead(200, { 'Content-Type': 'text/html' }); response.end(document);
  });
  await new Promise<void>(resolve => source.listen(0, '127.0.0.1', resolve));
  const address = source.address();
  if (!address || typeof address === 'string') throw new Error('Missing fixture port');
  const url = `http://127.0.0.1:${address.port}/storage`;
  const harness = await launchExtension(['cookies', 'tabs', 'scripting'], ['<all_urls>']);
  try {
    const target = await harness.context.newPage();
    await target.goto(url);
    await target.evaluate(() => { localStorage.setItem('account', 'alternate-account'); sessionStorage.setItem('session', 'preserve-me'); });
    await harness.context.addCookies([{ name: 'login', value: 'selected-login', url }]);
    const page = await harness.context.newPage();
    await page.goto(`chrome-extension://${harness.id}/options.html`);
    await page.getByRole('button', { name: 'Configuration', exact: true }).click();
    await page.getByLabel('ArchiveBox Server URL', { exact: true }).fill(archivebox.server);
    await page.getByLabel('ArchiveBox Server URL', { exact: true }).blur();
    await page.getByLabel('API Key', { exact: true }).fill(archivebox.key);
    await page.getByLabel('API Key', { exact: true }).blur();
    await waitForSavedSettings(page);
    await page.getByRole('button', { name: 'Cookies', exact: true }).click();
    await page.getByRole('checkbox', { name: 'Select 127.0.0.1', exact: true }).check();
    await page.getByRole('button', { name: 'Add to Private', exact: true }).click();
    const uploads: any[] = [];
    page.on('request', request => { if (request.url().endsWith('/api/v1/personas/sync')) uploads.push(request.postDataJSON()); });
    await page.getByRole('button', { name: 'Sync now', exact: true }).click();
    await expect(page.locator('.persona-sync-time time')).toBeVisible();
    const first = await page.locator('.persona-sync-time time').getAttribute('datetime');
    expect(uploads[0].auth_json.origins[0].localStorage).toContainEqual({ name: 'account', value: 'alternate-account' });
    expect(uploads[0].auth_json.tabs[0].sessionStorage).toContainEqual({ name: 'session', value: 'preserve-me' });
    await page.bringToFront();
    const discarded = await page.evaluate(async url => {
      const api = (globalThis as typeof globalThis & { chrome: typeof browser }).chrome;
      const tab = (await api.tabs.query({})).find(tab => tab.url === url)!;
      return (await api.tabs.discard(tab.id!))?.discarded;
    }, url);
    expect(discarded).toBe(true);
    await page.getByRole('button', { name: 'Sync now', exact: true }).click();
    await expect(page.getByRole('button', { name: 'Sync now', exact: true })).toBeEnabled();
    await expect(page.locator('.persona-sync-time time')).not.toHaveAttribute('datetime', first!);
    await expect(page.locator('.persona .status.error')).toHaveCount(0);
    expect(uploads).toHaveLength(2);
    expect(uploads[1].auth_json.origins).toEqual(uploads[0].auth_json.origins);
    expect(uploads[1].auth_json.tabs).toEqual(uploads[0].auth_json.tabs);
    expect(uploads[1].auth_json.cookies).toEqual(uploads[0].auth_json.cookies);
  } finally {
    await harness.close();
    await new Promise<void>((resolve, reject) => source.close(error => error ? reject(error) : resolve()));
  }
});

// One open tab whose page the extension cannot read must not block uploading
// the profile's cookies. That tab's last saved browser storage is kept.
for (const [name, makeUnreadable] of [
  ['a matching tab showing an error page', async (harness: Awaited<ReturnType<typeof launchExtension>>, url: string) => {
    await expect((await harness.context.newPage()).goto(`${url}/error`)).rejects.toThrow(/ERR_HTTP_RESPONSE_CODE_FAILURE/);
  }],
  ['site access restricted in browser settings', async (harness: Awaited<ReturnType<typeof launchExtension>>) => {
    const extensions = await harness.context.newPage();
    await extensions.goto('chrome://extensions');
    // The real "Site access: On specific sites" control, keeping only the ArchiveBox server.
    await extensions.evaluate(async id => {
      const developer = (globalThis as typeof globalThis & { chrome: any }).chrome.developerPrivate;
      await developer.updateExtensionConfiguration({ extensionId: id, hostAccess: 'ON_SPECIFIC_SITES' });
      await developer.addHostPermission(id, 'http://localhost/*');
    }, harness.id);
    await extensions.close();
  }],
] as const) test(`${name} keeps saved browser storage without blocking persona sync`, async ({ archivebox }) => {
  const source = createServer((request, response) => {
    response.writeHead(request.url === '/error' ? 500 : 200, { 'Content-Type': 'text/html' });
    response.end(request.url === '/error' ? '' : '<p>signed in</p>');
  });
  await new Promise<void>(resolve => source.listen(0, '127.0.0.1', resolve));
  const address = source.address();
  if (!address || typeof address === 'string') throw new Error('Missing fixture port');
  const origin = `http://127.0.0.1:${address.port}`;
  const harness = await launchExtension(['cookies', 'tabs', 'scripting'], ['<all_urls>']);
  try {
    const target = await harness.context.newPage();
    await target.goto(`${origin}/storage`);
    await target.evaluate(() => { localStorage.setItem('account', 'alternate-account'); sessionStorage.setItem('session', 'preserve-me'); });
    const second = await harness.context.newPage();
    await second.goto(`${origin}/second`);
    await second.evaluate(() => sessionStorage.setItem('session', 'second-tab'));
    await harness.context.addCookies([{ name: 'login', value: 'selected-login', url: origin }]);
    const page = await harness.context.newPage();
    await page.goto(`chrome-extension://${harness.id}/options.html`);
    await page.getByRole('button', { name: 'Configuration', exact: true }).click();
    await page.getByLabel('ArchiveBox Server URL', { exact: true }).fill(archivebox.server);
    await page.getByLabel('ArchiveBox Server URL', { exact: true }).blur();
    await page.getByLabel('API Key', { exact: true }).fill(archivebox.key);
    await page.getByLabel('API Key', { exact: true }).blur();
    await waitForSavedSettings(page);
    await page.getByRole('button', { name: 'Cookies', exact: true }).click();
    await page.getByRole('checkbox', { name: 'Select 127.0.0.1', exact: true }).check();
    await page.getByRole('button', { name: 'Add to Private', exact: true }).click();
    const uploads: any[] = [];
    page.on('request', request => { if (request.url().endsWith('/api/v1/personas/sync')) uploads.push(request.postDataJSON()); });
    await page.getByRole('button', { name: 'Sync now', exact: true }).click();
    await expect(page.locator('.persona-sync-time time')).toBeVisible();
    const first = await page.locator('.persona-sync-time time').getAttribute('datetime');
    // Both tabs share the origin's localStorage, exported once; each keeps its own sessionStorage.
    expect(uploads[0].auth_json.origins).toHaveLength(1);
    expect(uploads[0].auth_json.origins[0].localStorage).toContainEqual({ name: 'account', value: 'alternate-account' });
    expect(uploads[0].auth_json.tabs).toEqual(expect.arrayContaining([
      { url: `${origin}/storage`, sessionStorage: [{ name: 'session', value: 'preserve-me' }] },
      { url: `${origin}/second`, sessionStorage: [{ name: 'session', value: 'second-tab' }] },
    ]));
    expect(uploads[0].auth_json.tabs).toHaveLength(2);

    await makeUnreadable(harness, origin);
    await page.bringToFront();
    await page.getByRole('button', { name: 'Sync now', exact: true }).click();
    await expect(page.getByRole('button', { name: 'Sync now', exact: true })).toBeEnabled();
    await expect(page.locator('.persona .status.error')).toHaveCount(0);
    await expect(page.locator('.persona-sync-time time')).not.toHaveAttribute('datetime', first!);
    expect(uploads).toHaveLength(2);
    expect(uploads[1].auth_json.cookies).toEqual(uploads[0].auth_json.cookies);
    expect(uploads[1].auth_json.origins).toEqual(uploads[0].auth_json.origins);
    expect(uploads[1].auth_json.tabs).toEqual(uploads[0].auth_json.tabs);
    const synced = (await archivebox.api('/api/v1/personas/personas?limit=100')).items;
    expect(synced.find((persona: any) => persona.name === 'Private')).toBeTruthy();
  } finally {
    await harness.close();
    await new Promise<void>((resolve, reject) => source.close(error => error ? reject(error) : resolve()));
  }
});

test('saving from the popup still archives while the persona cookie sync is failing', async ({ archivebox }) => {
  // Several origins on one host, all covered by the profile's 127.0.0.1 cookie domain.
  const sources = await Promise.all(Array.from({ length: 6 }, async () => {
    const source = createServer((_request, response) => {
      response.writeHead(200, { 'Content-Type': 'text/html' }); response.end('<title>Signed in</title><p>signed in</p>');
    });
    await new Promise<void>(resolve => source.listen(0, '127.0.0.1', resolve));
    const address = source.address();
    if (!address || typeof address === 'string') throw new Error('Missing fixture port');
    return { source, origin: `http://127.0.0.1:${address.port}` };
  }));
  const { origin } = sources[0]!;
  const harness = await launchExtension(['cookies', 'tabs', 'scripting'], ['<all_urls>']);
  try {
    const target = await harness.context.newPage();
    await target.goto(`${origin}/signed-in`);
    await harness.context.addCookies([{ name: 'login', value: 'first-login', url: origin }]);
    const options = await harness.context.newPage();
    await options.goto(`chrome-extension://${harness.id}/options.html`);
    await options.getByRole('button', { name: 'Configuration', exact: true }).click();
    await options.getByLabel('ArchiveBox Server URL', { exact: true }).fill(archivebox.server);
    await options.getByLabel('ArchiveBox Server URL', { exact: true }).blur();
    await options.getByLabel('API Key', { exact: true }).fill(archivebox.key);
    await options.getByLabel('API Key', { exact: true }).blur();
    await options.getByLabel('Save viewport screenshots locally', { exact: true }).uncheck();
    await options.getByLabel('Save MHTML snapshots locally', { exact: true }).uncheck();
    await options.getByLabel('Default logged-in persona', { exact: true }).selectOption('Private');
    await waitForSavedSettings(options);
    await options.getByRole('button', { name: 'Cookies', exact: true }).click();
    await options.getByRole('tab', { name: 'Private', exact: true }).click();
    await options.getByRole('checkbox', { name: 'Select 127.0.0.1', exact: true }).check();
    await options.getByRole('button', { name: 'Add to Private', exact: true }).click();
    const uploads: number[] = [];
    harness.context.on('response', response => { if (response.url().endsWith('/api/v1/personas/sync')) uploads.push(response.status()); });
    await options.getByRole('button', { name: 'Sync now', exact: true }).click();
    await expect(options.locator('.persona-sync-time time')).toBeVisible();
    expect(uploads).toEqual([200]);

    // The sites now hold more browser storage than ArchiveBox accepts in one
    // request (25 MB), so every upload of this profile is rejected.
    for (const { origin: site } of sources) {
      const page = await harness.context.newPage();
      await page.goto(`${site}/storage`);
      await page.evaluate(() => localStorage.setItem('cache', 'x'.repeat(4_500_000)));
    }
    await harness.context.addCookies([{ name: 'login', value: 'refreshed-login', url: origin }]);

    const popup = await harness.context.newPage();
    await target.bringToFront();
    await popup.goto(`chrome-extension://${harness.id}/popup.html`);
    await expect(popup.getByRole('button', { name: 'Persona', exact: true })).toContainText('Private');
    await expect.poll(async () => {
      const snapshot = (await readSnapshots(options)).find(item => item.url === `${origin}/signed-in`);
      const copy = Object.values(snapshot?.remote_copies || {})[0];
      return copy?.snapshot_id ? (await archivebox.api(`/api/v1/core/snapshot/${copy.snapshot_id}`)).url : copy?.status;
    }, { timeout: 30_000 }).toBe(`${origin}/signed-in`);
    expect(uploads.length).toBeGreaterThan(1);
    expect(uploads.slice(1).every(status => status >= 400)).toBe(true);
    // The failed upload is still reported and retried in settings.
    await options.bringToFront();
    await expect(options.getByRole('status').filter({ hasText: 'Cookie sync failed; retrying automatically' })).toBeVisible();
  } finally {
    await harness.close();
    for (const { source } of sources) await new Promise<void>((resolve, reject) => source.close(error => error ? reject(error) : resolve()));
  }
});

import { expect, test } from '@playwright/test';
import { launchExtension, readSnapshots, seedSnapshots } from './helpers/extension';
import type { Snapshot } from '../src/lib/types';

test('searched pages retain date, title, tag, and offset semantics', async () => {
  const harness = await launchExtension();
  try {
    const page = await harness.context.newPage();
    await page.goto(`chrome-extension://${harness.id}/options.html`);
    await expect(page.locator('.saved-url-count')).toBeVisible();
    await seedSnapshots(page, [
      ['a', 'Zulu title', 'research'],
      ['b', 'alpha title', 'research'],
      ['c', 'Beta Research', 'other'],
      ['d', 'literal "quote"', 'archive'],
      ['e', 'An unrelated row', 'misc'],
    ].map(([id, title, tag], index) => ({
      id: id!, title: title!, tags: [tag!], url: `https://example.com/article/${id}`,
      timestamp: `2026-01-0${index + 1}T00:00:00.000Z`, depth: 0,
    })));
    const results = await page.evaluate(async () => {
      const models = (globalThis as unknown as { archiveboxModels: {
        listSnapshots(query: object, sort: object, page: object): Promise<{ snapshots: Snapshot[]; hasMore: boolean }>;
      } }).archiveboxModels;
      const read = async (search: string, key: string, direction: string, offset: number, limit: number) => {
        const result = await models.listSnapshots({ search }, { key, direction }, { offset, limit });
        return { ids: result.snapshots.map(row => row.id), tags: result.snapshots.map(row => row.tags), hasMore: result.hasMore };
      };
      return {
        oldest: await read('research', 'date', 'asc', 0, 2),
        newest: await read('research', 'date', 'desc', 0, 2),
        title: await read('research', 'title', 'asc', 1, 1),
        reverseTitle: await read('research', 'title', 'desc', 1, 1),
        lastPage: await read('research', 'title', 'asc', 2, 1),
        terms: await read('research title', 'date', 'asc', 0, 10),
        quoted: await read('"quote"', 'date', 'asc', 0, 10),
        url: await read('article/e', 'date', 'desc', 0, 10),
        unfiltered: await read('', 'date', 'asc', 3, 1),
      };
    });
    expect(results.oldest).toEqual({ ids: ['a', 'b'], tags: [['research'], ['research']], hasMore: true });
    expect(results.newest.ids).toEqual(['c', 'b']);
    expect(results.title).toEqual({ ids: ['c'], tags: [['other']], hasMore: true });
    expect(results.reverseTitle.ids).toEqual(['c']);
    expect(results.lastPage).toEqual({ ids: ['a'], tags: [['research']], hasMore: false });
    expect(results.terms.ids).toEqual(['a', 'b']);
    expect(results.quoted.ids).toEqual(['d']);
    expect(results.url.ids).toEqual(['e']);
    expect(results.unfiltered).toEqual({ ids: ['d'], tags: [['archive']], hasMore: true });
  } finally {
    await harness.close();
  }
});

test('two open options pages preserve concurrent tags on the same SQLite snapshot', async () => {
  const harness = await launchExtension();
  try {
    const first = await harness.context.newPage();
    await first.goto(`chrome-extension://${harness.id}/options.html`);
    await expect(first.locator('.saved-url-count')).toBeVisible();
    await seedSnapshots(first, [{ id: 'concurrent-tags', url: 'https://archivebox.io/tests/?tags',
      timestamp: '2026-01-01T00:00:00.000Z', title: 'Concurrent tags', tags: ['original'], depth: 0 }]);
    const second = await harness.context.newPage();
    await second.goto(`chrome-extension://${harness.id}/options.html`);
    for (const [page, tag] of [[first, 'first'], [second, 'second']] as const) {
      await page.locator('.saved-url-table').getByTitle('Add tag', { exact: true }).click();
      await page.getByPlaceholder('tag', { exact: true }).fill(tag);
    }
    await Promise.all([first, second].map(page => page.getByPlaceholder('tag', { exact: true }).press('Enter')));
    await expect.poll(async () => (await readSnapshots(first))[0]?.tags.slice().sort()).toEqual(['first', 'original', 'second']);
    for (const page of [first, second]) {
      await page.reload();
      for (const tag of ['first', 'original', 'second']) {
        await expect(page.locator('.saved-url-table').getByTitle(`Remove tag ${tag}`, { exact: true })).toBeVisible();
      }
    }
  } finally {
    await harness.close();
  }
});

import { expect, test } from '@playwright/test';
import { readdir, readFile } from 'node:fs/promises';
import path from 'node:path';

// models.ts is the only door to saved data, so the storage backend can be
// replaced in one file. These checks fail when other code reaches past it.
async function sourceFiles(directory: string): Promise<string[]> {
  const entries = await readdir(directory, { withFileTypes: true });
  return (await Promise.all(entries.map(async (entry) => {
    const file = path.join(directory, entry.name);
    if (entry.isDirectory()) return sourceFiles(file);
    return /\.(ts|tsx)$/.test(entry.name) ? [file] : [];
  }))).flat();
}

test('only models.ts touches the database, OPFS, or the legacy entries key', async () => {
  const files = [...await sourceFiles('src'), ...await sourceFiles('entrypoints')];
  const violations: string[] = [];
  for (const file of files) {
    const relative = path.relative('.', file);
    const source = await readFile(file, 'utf8');
    const rules: Array<[RegExp, string[]]> = [
      // The SQLite engine, the schema, and the OPFS file layer are private to models.ts.
      [/from ['"][^'"]*\/(sqlite|schema|opfs)['"]/, ['src/lib/models.ts']],
      [/drizzle-orm|@journeyapps\/wa-sqlite/, ['src/lib/models.ts', 'src/lib/schema.ts', 'src/lib/sqlite.ts']],
      [/navigator\.storage\.getDirectory\(/, ['src/lib/opfs.ts']],
      // The pre-SQLite snapshot array: read once by the migrations, never again.
      [/['"]entries['"]/, ['src/lib/models.ts', 'src/lib/storage_migration.ts']],
    ];
    for (const [pattern, allowed] of rules) {
      if (pattern.test(source) && !allowed.includes(relative)) violations.push(`${relative}: ${pattern}`);
    }
  }
  expect(violations).toEqual([]);
});

// Exercise the task form against real ArchiveBox and OpenCode, with no mocked API.
import { expect } from '@playwright/test';
import { readFile, mkdir } from 'node:fs/promises';
import { launchExtension, readSnapshots, waitForSavedSettings } from '../tests/helpers/extension.ts';

const server = process.env.ARCHIVEBOX_TEST_SERVER;
const keyFile = process.env.ARCHIVEBOX_TEST_KEY_FILE;
if (!server || !keyFile) throw new Error('Set ARCHIVEBOX_TEST_SERVER and ARCHIVEBOX_TEST_KEY_FILE. Enable OpenCode on that disposable server.');
const key = (await readFile(keyFile, 'utf8')).trim();
const evidence = process.env.ARCHIVEBOX_TEST_EVIDENCE;
if (evidence) await mkdir(evidence, { recursive: true });
const harness = await launchExtension(['tabs'], ['<all_urls>']);
try {
  const { context, id } = harness;
  const options = await context.newPage();
  await options.goto(`chrome-extension://${id}/options.html`);
  await options.getByRole('button', { name: 'Configuration', exact: true }).click();
  await options.getByLabel('Save viewport screenshots locally', { exact: true }).uncheck();
  await options.getByLabel('Save MHTML snapshots locally', { exact: true }).uncheck();
  const address = options.getByPlaceholder('http://localhost:5797 or https://archivebox.example.com');
  await address.fill(server); await address.blur();
  const token = [REDACTED]'... abcexamplekey1234 ...');
  await token.fill(key); await token.blur();
  const registry = () => options.evaluate(async () => (await chrome.storage.local.get('server_registry')).server_registry);
  await expect.poll(async () => Boolean((await registry())?.servers[0]?.token)).toBe(true);
  await waitForSavedSettings(options);
  const serverId = (await registry()).active_server_id;
  const entries = () => readSnapshots(options);
  const target = await context.newPage();
  const url = `https://example.com/?archivebox-agent-task=${Date.now()}`;
  await target.goto(url);
  const popup = await context.newPage();
  await target.bringToFront();
  await popup.goto(`chrome-extension://${id}/popup.html`);
  const entry = async () => (await entries()).find(item => item.url === url);
  await expect.poll(async () => (await entry())?.remote_copies?.[serverId]?.snapshot_id, { timeout: 30000 }).toBeTruthy();
  const before = (await entry()).remote_copies[serverId];
  await popup.getByRole('button', { name: 'Ask AI about this capture' }).click();
  const task = popup.getByLabel('What should AI do with this capture?');
  await expect(task).toBeFocused();
  await expect(popup.getByRole('button', { name: 'Send', exact: true })).toBeDisabled();
  const prompt = 'Reply with CAPTURE_TASK_ACCEPTED. Do not modify files or start other captures.';
  await task.fill(prompt);
  const touch = await context.newCDPSession(popup);
  await touch.send('Emulation.setTouchEmulationEnabled', { enabled: true });
  for (const width of [320, 375, 480, 560]) {
    await popup.setViewportSize({ width, height: 600 });
    expect(await popup.evaluate(() => document.documentElement.scrollWidth)).toBe(width);
    const controls = await popup.locator('.archivebox-overlay__header > *').evaluateAll(nodes => nodes.map(node => node.getBoundingClientRect().y));
    expect(new Set(controls).size).toBe(1);
    if (evidence && width === 320) await popup.locator('.archivebox-overlay').screenshot({ path: `${evidence}/agent-task-mobile.png` });
  }
  await touch.send('Emulation.setTouchEmulationEnabled', { enabled: false });
  if (evidence) await popup.locator('.archivebox-overlay').screenshot({ path: `${evidence}/agent-task-form.png` });
  await context.setOffline(true);
  await task.press('Enter');
  await expect(popup.getByRole('alert')).toBeVisible();
  await expect(task).toHaveValue(prompt);
  expect((await entry()).remote_copies[serverId].agent_task).toBeUndefined();
  await context.setOffline(false);
  await task.press('Enter');
  await expect(popup.getByRole('button', { name: 'AI task submitted — open session' })).toBeVisible({ timeout: 120000 });
  await expect(task).toHaveCount(0);
  const after = (await entry()).remote_copies[serverId];
  expect(after.snapshot_id).toBe(before.snapshot_id);
  expect(after.crawl_id).toBe(before.crawl_id);
  expect(after.submitted_at).toBe(before.submitted_at);
  const receipt = after.agent_task;
  expect(receipt.session_id).toMatch(/^ses_/);
  const tabs = await options.evaluate(async () => chrome.tabs.query({}));
  const sessionTab = tabs.find(tab => tab.url?.includes(encodeURIComponent(receipt.session_id)) || tab.url?.includes(receipt.session_id));
  expect(sessionTab).toBeTruthy();
  expect(sessionTab.active).toBe(false);

  // Authenticate the real admin UI and verify the persisted OpenCode message.
  const login = await fetch(`${server}/api/v1/auth/browser_session`, { method: 'POST', headers: { Authorization: `Bearer ${key}` } });
  expect(login.status).toBe(200);
  const auth = await login.json();
  await context.addCookies([{ name: auth.cookie.name, value: auth.cookie.value, url: auth.admin_url, httpOnly: true, secure: auth.cookie.secure, sameSite: 'Lax' }]);
  const admin = new URL(auth.admin_url).origin;
  const messages = await context.request.get(`${admin}/admin/agent/opencode/session/${receipt.session_id}/message`);
  expect(messages.status()).toBe(200);
  const stored = await messages.json();
  const text = stored.filter(message => message.info.role === 'user').flatMap(message => message.parts).filter(part => part.type === 'text').map(part => part.text).join('\n');
  expect(text).toContain(prompt);
  expect(text.replaceAll('-', '')).toContain(before.snapshot_id.replaceAll('-', ''));
  expect(text).toContain(url);
  expect(text).toContain('Example Domain');
  const wrapper = await context.request.get(receipt.session_url);
  expect(wrapper.status()).toBe(200);
  expect(await wrapper.text()).toContain(`/session/${receipt.session_id}`);
