import { archiveBoxServerUrlMatches } from './archiveboxUrlExclusions';
import { capturePlugins } from './captureStatus';
import { snapshotRelativePath } from './opfs';
import { defaultServerPolicy, defaultServers } from './server_registry';
import { getConfig } from './storage';
import { migratePublishedStorage } from './storage_migration';
import type { CaptureKind, ConfigState, RemoteCopy, ServerConfiguration, Snapshot } from './types';
import { uuidv7 } from './uuid';

const { core_archiveresult, core_snapshot, core_snapshot_tags, core_tag, remote_copies } = schema;

// The one module that reads or writes saved data: snapshots, their capture
// results, per-server receipts, and the capture files in OPFS. Everything else
// imports from here, never from ./sqlite, ./schema or ./opfs, so the storage
// backend can change in this file alone (tests/models.test.ts enforces it).
// The tables are defined in ./schema.ts, mirroring the ArchiveBox server.
//
// Every operation is an indexed lookup or a bounded page, the same at 100 or
// 1M snapshots: an id, a URL, a page of a sorted or searched list, or a walk
// over the rows in fixed-size batches. Nothing loads the whole collection.

export {
  appendSnapshotScreenshotParts, assertLocalCaptureStorageAvailable, composeSnapshotScreenshotBlob,
  deleteSnapshotOpfs as deleteSnapshotFiles, readSnapshotMhtmlBlob, readSnapshotOpfsFiles as readSnapshotFiles,
  readSnapshotScreenshotBlob, readSnapshotScreenshotBlobs, readSnapshotSingleFileBlob, snapshotRelativePath,
  writeSnapshotMhtmlBytes, writeSnapshotScreenshot, writeSnapshotScreenshotParts, writeSnapshotSingleFileHtml,
} from './opfs';

type Tx = Orm<typeof schema>;
const captureKinds = Object.keys(capturePlugins) as CaptureKind[];
const batchSize = 500;

// Generated by `pnpm db:generate` from schema.ts (plus hand-written ones for
// what Drizzle cannot express), applied in file-name order. PRAGMA
// user_version counts how many have run.
const migrations = Object.entries(import.meta.glob<string>('../../drizzle/*.sql', { query: '?raw', import: 'default', eager: true }))
  .sort(([a], [b]) => a.localeCompare(b)).map(([, script]) => script);

let ready: Promise<Database<typeof schema>> | undefined;

// Opens the database, applies migrations, and moves pre-3.4 data out of
// chrome.storage.local, once per context. Every export awaits this.
function db(): Promise<Database<typeof schema>> {
  ready ??= (async () => {
    await migratePublishedStorage();
    const connection = await database(schema);
    await connection.migrate(migrations);
    await importLegacyEntries(connection);
    return connection;
  })().catch((error) => {
    ready = undefined;
    throw error;
  });
  return ready;
}

// storage_schema_version 1 kept every snapshot in one chrome.storage.local
// `entries` array. Version 2 moves them into SQLite, once, in batches. Each
// batch is an idempotent upsert keyed by id, so a worker stopped midway just
// redoes it on the next start; the version flips only after every id is
// confirmed in the database. The array is kept, unread, as entries_backup_v1
// for one release so a downgrade can be recovered.
async function importLegacyEntries(connection: Database<typeof schema>): Promise<void> {
  // getConfig also enters the storage migration lock. Web Locks are not
  // reentrant: read configuration before acquiring it or first-run UI freezes.
  const config = await getConfig();
  await navigator.locks.request('archivebox-storage-migration', async () => {
    const { storage_schema_version } = await browser.storage.local.get('storage_schema_version');
    if (storage_schema_version === 2) return;
    if (storage_schema_version !== 1) throw new Error('Unsupported extension storage version.');
    const { entries } = await browser.storage.local.get('entries');
    const unique = new Map<string, Snapshot>();
    for (const entry of Array.isArray(entries) ? entries as Snapshot[] : []) {
      if (entry && typeof entry.id === 'string' && typeof entry.url === 'string') unique.set(entry.id, entry);
    }
    const snapshots = [...unique.values()];
    for (let start = 0; start < snapshots.length; start += batchSize) {
      const batch = snapshots.slice(start, start + batchSize);
      await connection.transaction(async (tx) => {
        for (const snapshot of batch) await writeSnapshot(tx, snapshot, config);
      });
      const ids = batch.map(snapshot => snapshot.id);
      const [saved] = await connection.orm.select({ count: count() }).from(core_snapshot).where(inArray(core_snapshot.id, ids));
      if (saved?.count !== ids.length) throw new Error('Saved snapshots could not be moved to the new database.');
    }
    // Older versions also left copies in storage.sync. Nothing reads them;
    // keep them with the backup instead of in the user's sync quota.
    const { entries: syncEntries } = await browser.storage.sync.get('entries').catch(() => ({ entries: undefined }));
    await browser.storage.local.set({ storage_schema_version: 2,
      entries_backup_v1: { entries: entries ?? [], ...(syncEntries ? { sync_entries: syncEntries } : {}) } });
    await browser.storage.local.remove('entries');
    if (syncEntries) await browser.storage.sync.remove('entries');
  });
}

// --- Retention schedule (the server's ModelWithDeleteAfter.delete_at) ---------
// A snapshot row, or one of its captures, may be deleted locally once every
// server it was sent to has confirmed it and the configured retention period
// has passed since. These compute that moment (null: never, or not yet
// confirmed); retention.ts deletes what is due, after re-confirming with the
// server.

function captureRetention(kind: CaptureKind, config: ConfigState): number | null {
  if (!config.save_snapshots_locally) return 0;
  let ttl = config.capture_retention_ms[kind] ?? config.local_retention_ms;
  // A capture never outlives its snapshot.
  if (config.local_retention_ms !== 'never' && (ttl === 'never' || ttl > config.local_retention_ms)) ttl = config.local_retention_ms;
  return ttl === 'never' ? null : ttl;
}

function snapshotServers(snapshot: Snapshot, config: ConfigState): ServerConfiguration[] | null {
  const ids = Object.keys(snapshot.remote_copies || {});
  const servers = ids.map(id => config.servers.find(server => server.id === id));
  return ids.length && servers.every(Boolean) && !snapshot.unassigned_remote_copy ? servers as ServerConfiguration[] : null;
}

function latest(times: Array<string | undefined>): number {
  return Math.max(...times.map(time => Date.parse(time || '')).filter(Number.isFinite));
}

export function snapshotDeleteAt(snapshot: Snapshot, config: ConfigState): string | null {
  const ttl = config.save_snapshots_locally ? config.local_retention_ms : 0;
  const servers = snapshotServers(snapshot, config);
  if (ttl === 'never' || !servers) return null;
  let confirmed = -Infinity;
  for (const server of servers) {
    const copy = snapshot.remote_copies![server.id]!;
    const submitted = latest([copy.submitted_at, ...Object.values(copy.artifacts || {}).map(receipt => receipt?.uploaded_at)]);
    if (copy.status !== 'complete' || !Number.isFinite(submitted)
      || copy.submitted_to !== new URL(server.server).toString().replace(/\/$/, '')) return null;
    confirmed = Math.max(confirmed, submitted);
  }
  return new Date(confirmed + ttl).toISOString();
}

export function archiveResultDeleteAt(snapshot: Snapshot, kind: CaptureKind, config: ConfigState): string | null {
  const capture = snapshot[kind];
  const ttl = captureRetention(kind, config);
  const servers = snapshotServers(snapshot, config);
  if (!capture || ttl === null || !servers) return null;
  let confirmed = -Infinity;
  for (const server of servers) {
    const copy = snapshot.remote_copies![server.id]!;
    const receipt = copy.artifacts?.[kind];
    const uploaded = Date.parse(receipt?.uploaded_at || '');
    if (copy.submitted_to !== server.server || receipt?.status !== 'uploaded' || receipt.path !== capture.path
      || receipt.captured_at !== capture.capturedAt || !Number.isFinite(uploaded)) return null;
    confirmed = Math.max(confirmed, uploaded);
  }
  return new Date(confirmed + ttl).toISOString();
}

// --- Row mapping ----------------------------------------------------------------

async function writeSnapshot(tx: Tx, snapshot: Snapshot, config: ConfigState): Promise<void> {
  const now = new Date().toISOString();
  const { id, url, title = '', tags = [] } = snapshot;
  const fields = {
    modified_at: now,
    created_by_username: snapshot.created_by_username || 'system',
    url,
    bookmarked_at: snapshot.timestamp,
    title,
    depth: snapshot.depth ?? 0,
    delete_at: snapshotDeleteAt(snapshot, config),
    favIconUrl: snapshot.favIconUrl ?? null,
    persona_overrides: snapshot.persona_overrides ?? null,
    unassigned_remote_copy: snapshot.unassigned_remote_copy ?? null,
  };
  await tx.insert(core_snapshot).values({ id, created_at: now, ...fields }).onConflictDoUpdate({ target: core_snapshot.id, set: fields });
  await tx.run(sql`INSERT OR REPLACE INTO search_index (rowid, snapshot_id, url, title, content)
    SELECT rowid, id, url, title, ${tags.join(' ')} FROM core_snapshot WHERE id = ${id}`);

  // Tags keep the order they were added in (core_snapshot_tags.id); only new
  // ones are inserted, so unchanged tags keep their rows.
  const names = [...new Set(tags.filter(Boolean))];
  await tx.delete(core_snapshot_tags).where(and(eq(core_snapshot_tags.snapshot_id, id), notInArray(core_snapshot_tags.tag_id,
    tx.select({ id: core_tag.id }).from(core_tag).where(inArray(core_tag.name, names)))));
  for (const name of names) {
    const [tag] = await tx.insert(core_tag).values({ created_at: now, modified_at: now, name })
      .onConflictDoUpdate({ target: core_tag.name, set: { name } }).returning({ id: core_tag.id });
    await tx.insert(core_snapshot_tags).values({ snapshot_id: id, tag_id: tag!.id }).onConflictDoNothing();
  }

  // One ArchiveResult per capture, as the server records each plugin's run.
  // output_json holds the local capture record; output_files lists its files
  // relative to the plugin folder, like the server's.
  for (const kind of captureKinds) {
    const capture = snapshot[kind];
    if (!capture) {
      await tx.delete(core_archiveresult).where(and(eq(core_archiveresult.snapshot_id, id), eq(core_archiveresult.plugin, capturePlugins[kind])));
      continue;
    }
    const paths = 'parts' in capture && capture.parts?.length ? capture.parts.map(part => part.path) : [capture.path];
    const files = paths.map(path => snapshotRelativePath(snapshot, path)?.split('/').slice(1).join('/') || path);
    const result = {
      modified_at: now, status: 'succeeded', end_ts: capture.capturedAt, output_str: files[0]!, output_json: capture,
      output_files: Object.fromEntries(files.map(file => [file, {}])), output_size: 'size' in capture ? capture.size : 0,
      delete_at: archiveResultDeleteAt(snapshot, kind, config),
    };
    await tx.insert(core_archiveresult).values({ id: uuidv7(), created_at: now, snapshot_id: id, plugin: capturePlugins[kind], ...result })
      .onConflictDoUpdate({ target: [core_archiveresult.snapshot_id, core_archiveresult.plugin, core_archiveresult.hook_name], set: result });
  }

  const copies = Object.entries(snapshot.remote_copies || {});
  await tx.delete(remote_copies).where(and(eq(remote_copies.snapshot_id, id), notInArray(remote_copies.server_id, copies.map(([server]) => server))));
  for (const [server_id, remote_copy] of copies) {
    await tx.insert(remote_copies).values({ snapshot_id: id, server_id, remote_copy })
      .onConflictDoUpdate({ target: [remote_copies.snapshot_id, remote_copies.server_id], set: { remote_copy } });
  }
}

type SnapshotRow = typeof core_snapshot.$inferSelect;

// Reassembles rows into the Snapshot shape callers use.
async function readSnapshots(tx: Tx, rows: SnapshotRow[]): Promise<Snapshot[]> {
  if (!rows.length) return [];
  const ids = rows.map(row => row.id);
  const tags = await tx.select({ snapshot_id: core_snapshot_tags.snapshot_id, name: core_tag.name }).from(core_snapshot_tags)
    .innerJoin(core_tag, eq(core_tag.id, core_snapshot_tags.tag_id))
    .where(inArray(core_snapshot_tags.snapshot_id, ids)).orderBy(core_snapshot_tags.id);
  const results = await tx.select({ snapshot_id: core_archiveresult.snapshot_id, plugin: core_archiveresult.plugin, output_json: core_archiveresult.output_json })
    .from(core_archiveresult).where(inArray(core_archiveresult.snapshot_id, ids));
  const copies = await tx.select().from(remote_copies).where(inArray(remote_copies.snapshot_id, ids));
  return rows.map(row => {
    const snapshot: Snapshot = {
      id: row.id, url: row.url, timestamp: row.bookmarked_at, created_by_username: row.created_by_username,
      title: row.title, depth: row.depth as Snapshot['depth'],
      tags: tags.filter(tag => tag.snapshot_id === row.id).map(tag => tag.name),
    };
    if (row.favIconUrl !== null) snapshot.favIconUrl = row.favIconUrl;
    if (row.persona_overrides !== null) snapshot.persona_overrides = row.persona_overrides;
    if (row.unassigned_remote_copy !== null) snapshot.unassigned_remote_copy = row.unassigned_remote_copy as RemoteCopy;
    for (const result of results) {
      const kind = captureKinds.find(kind => capturePlugins[kind] === result.plugin);
      if (kind && result.snapshot_id === row.id) Object.assign(snapshot, { [kind]: result.output_json });
    }
    for (const copy of copies) {
      if (copy.snapshot_id === row.id) snapshot.remote_copies = { ...snapshot.remote_copies, [copy.server_id]: copy.remote_copy as RemoteCopy };
    }
    return snapshot;
  });
}

async function selectSnapshots(tx: Tx, where: SQL | undefined, options: { orderBy?: SQL[]; limit?: number; offset?: number } = {}): Promise<Snapshot[]> {
  let query = tx.select().from(core_snapshot).where(where).orderBy(...(options.orderBy ?? [])).$dynamic();
  if (options.limit !== undefined) {
    // Sort only rowids, then fetch the bounded page's full records. Broad FTS
    // matches otherwise copy every snapshot's fields into the temporary sort.
    const rowid = sql<number>`"core_snapshot".rowid`;
    const page = tx.select({ rowid }).from(core_snapshot).where(where).orderBy(...(options.orderBy ?? []))
      .limit(options.limit).offset(options.offset ?? 0);
    query = query.where(inArray(rowid, page));
  }
  return readSnapshots(tx, await query);
}

// New snapshots belong to the default server's user, like the server's
// created_by, so their captures land in users/{username}/. "system" (the
// server's built-in user) when no server is set up or it is too old to
// report a username.
function withOwner(snapshot: Snapshot, config: ConfigState): Snapshot {
  return { ...snapshot, created_by_username: snapshot.created_by_username || defaultServers(config)[0]?.username || 'system' };
}

// A configured ArchiveBox server's own pages are never saved.
function isServerPage(url: string, config: ConfigState): boolean {
  return config.servers.some(server => server.server && archiveBoxServerUrlMatches(server.server, url));
}

// --- Change notifications ---------------------------------------------------
// Each committed write posts the changed ids to every extension context (popup,
// options page, background). BroadcastChannel skips the sending context, so it
// is notified directly too.

export type SnapshotsChange = { ids: string[] };
const channelName = 'archivebox-snapshots';
const localListeners = new Set<(change: SnapshotsChange) => void>();
let channel: BroadcastChannel | undefined;

function notify(ids: string[]): void {
  channel ??= new BroadcastChannel(channelName);
  channel.postMessage({ ids });
  for (const listener of localListeners) listener({ ids });
}

export function onSnapshotsChanged(listener: (change: SnapshotsChange) => void): () => void {
  const remote = new BroadcastChannel(channelName);
  remote.onmessage = (event: MessageEvent<SnapshotsChange>) => listener(event.data);
  localListeners.add(listener);
  return () => { remote.close(); localListeners.delete(listener); };
}

// --- Reads --------------------------------------------------------------------

export async function getSnapshot(id: string): Promise<Snapshot | null> {
  const { transaction } = await db();
  return transaction(async tx => (await selectSnapshots(tx, eq(core_snapshot.id, id)))[0] ?? null);
}

export async function getSnapshots(ids: string[]): Promise<Snapshot[]> {
  if (!ids.length) return [];
  const { transaction } = await db();
  const found = await transaction(tx => selectSnapshots(tx, inArray(core_snapshot.id, ids)));
  return ids.flatMap(id => found.filter(snapshot => snapshot.id === id));
}

// A URL can have any number of snapshots (captures over time, or as different
// logged-in personas). Callers that show "this page's snapshot" use the newest.
export async function latestSnapshotForUrl(url: string): Promise<Snapshot | null> {
  const { transaction } = await db();
  return transaction(async tx => (await selectSnapshots(tx, eq(core_snapshot.url, url),
    { orderBy: [desc(core_snapshot.bookmarked_at)], limit: 1 }))[0] ?? null);
}

export type SnapshotQuery = { search?: string };
export type SnapshotSort = { key: 'date' | 'title'; direction: 'asc' | 'desc' };

// Every whitespace-separated term must appear in the URL, title or tags as a
// case-insensitive substring. The trigram index matches terms of 3+
// characters; shorter terms cannot be indexed and are ignored.
function searchFilter(query: SnapshotQuery): SQL | undefined {
  const terms = (query.search || '').split(/\s+/).filter(term => [...term].length >= 3);
  if (!terms.length) return undefined;
  const match = terms.map(term => `"${term.replaceAll('"', '""')}"`).join(' ');
  return sql`"core_snapshot".rowid IN (SELECT rowid FROM search_index WHERE search_index MATCH ${match})`;
}

// One page of snapshots for display, plus whether more follow. Pages of a
// configured server's own site (saved before that server was set up) are
// left out of the page, not deleted: removing the server shows them again.
export async function listSnapshots(query: SnapshotQuery, sort: SnapshotSort, page: { offset: number; limit: number }): Promise<{ snapshots: Snapshot[]; hasMore: boolean }> {
  const [{ transaction }, config] = await Promise.all([db(), getConfig()]);
  const order = sort.direction === 'asc' ? asc : desc;
  const rows = await transaction(tx => selectSnapshots(tx, searchFilter(query), {
    orderBy: [sort.key === 'title' ? order(sql`${core_snapshot.title} COLLATE NOCASE`) : order(core_snapshot.bookmarked_at)],
    limit: page.limit + 1, offset: page.offset,
  }));
  return { snapshots: rows.slice(0, page.limit).filter(snapshot => !isServerPage(snapshot.url, config)), hasMore: rows.length > page.limit };
}

export async function countSnapshots(query: SnapshotQuery = {}): Promise<number> {
  const { orm } = await db();
  const [result] = await orm.select({ count: count() }).from(core_snapshot).where(searchFilter(query));
  return result!.count;
}

// Calls fn with successive batches of rows, in insertion order. fn runs
// between database reads, so it may await anything, including writes.
async function walkSnapshots(where: SQL | undefined, fn: (batch: Snapshot[]) => Promise<void> | void): Promise<void> {
  const { transaction } = await db();
  const rowid = sql<number>`"core_snapshot".rowid`;
  let after = 0;
  for (;;) {
    const page = await transaction(async tx => {
      const rows = await tx.select({ rowid, row: core_snapshot }).from(core_snapshot)
        .where(and(where, gt(rowid, after))).orderBy(rowid).limit(batchSize);
      return { last: rows[rows.length - 1]?.rowid, snapshots: await readSnapshots(tx, rows.map(({ row }) => row)) };
    });
    if (page.last === undefined) return;
    after = page.last;
    await fn(page.snapshots);
  }
}

// The snapshots a search shows (see listSnapshots), in batches, for bulk
// actions on "everything matching".
export async function forEachSnapshot(query: SnapshotQuery, fn: (batch: Snapshot[]) => Promise<void> | void): Promise<void> {
  const config = await getConfig();
  await walkSnapshots(searchFilter(query), async (batch) => {
    const shown = batch.filter(snapshot => !isServerPage(snapshot.url, config));
    if (shown.length) await fn(shown);
  });
}

// Snapshots whose row or a capture is due for deletion (delete_at <= now),
// in batches; retention re-checks each one before deleting anything.
export async function forEachSnapshotDueForDeletion(fn: (batch: Snapshot[]) => Promise<void>): Promise<void> {
  const { transaction } = await db();
  const now = new Date().toISOString();
  let after = '';
  for (;;) {
    const page = await transaction(async tx => {
      const due = await tx.select({ id: core_snapshot.id }).from(core_snapshot)
        .where(and(lte(core_snapshot.delete_at, now), gt(core_snapshot.id, after)))
        .union(tx.select({ id: core_archiveresult.snapshot_id }).from(core_archiveresult)
          .where(and(lte(core_archiveresult.delete_at, now), gt(core_archiveresult.snapshot_id, after))))
        .orderBy(asc(core_snapshot.id)).limit(batchSize);
      const ids = due.map(row => row.id);
      return { last: ids[ids.length - 1], snapshots: ids.length ? await selectSnapshots(tx, inArray(core_snapshot.id, ids)) : [] };
    });
    if (page.last === undefined) return;
    after = page.last;
    await fn(page.snapshots);
  }
}

// Tag names, most recently applied first, for suggestions.
export async function snapshotTags(): Promise<string[]> {
  const { orm } = await db();
  return (await orm.select({ name: core_tag.name }).from(core_tag).orderBy(desc(core_tag.modified_at), core_tag.name)).map(row => row.name);
}

// [tag, number of snapshots], most used first.
export async function snapshotTagCounts(): Promise<Array<[string, number]>> {
  const { orm } = await db();
  return (await orm.select({ name: core_tag.name, num_snapshots: core_tag.num_snapshots }).from(core_tag)
    .orderBy(desc(core_tag.num_snapshots), core_tag.name)).map(row => [row.name, row.num_snapshots]);
}

// Which of these URLs already have a snapshot (for import "new" markers).
export async function savedSnapshotUrls(urls: string[]): Promise<Set<string>> {
  const { orm } = await db();
  const saved = new Set<string>();
  const unique = [...new Set(urls)];
  for (let start = 0; start < unique.length; start += batchSize) {
    const rows = await orm.selectDistinct({ url: core_snapshot.url }).from(core_snapshot)
      .where(inArray(core_snapshot.url, unique.slice(start, start + batchSize)));
    for (const row of rows) saved.add(row.url);
  }
  return saved;
}

// --- Writes -------------------------------------------------------------------

// The page's newest snapshot, or a new one from init when the URL has none.
// An existing snapshot only gains a missing title/favicon.
export async function ensureSnapshot(init: Snapshot): Promise<{ snapshot: Snapshot; created: boolean }> {
  const [{ transaction }, config] = await Promise.all([db(), getConfig()]);
  const result = await transaction(async tx => {
    const [existing] = await selectSnapshots(tx, eq(core_snapshot.url, init.url), { orderBy: [desc(core_snapshot.bookmarked_at)], limit: 1 });
    if (existing) {
      if ((existing.title || !init.title) && (existing.favIconUrl || !init.favIconUrl)) return { snapshot: existing, created: false, changed: false };
      const snapshot = { ...existing, title: existing.title || init.title, favIconUrl: existing.favIconUrl || init.favIconUrl || null };
      await writeSnapshot(tx, snapshot, config);
      return { snapshot, created: false, changed: true };
    }
    const snapshot = withOwner(init, config);
    if (isServerPage(init.url, config)) return { snapshot, created: true, changed: false };
    await writeSnapshot(tx, snapshot, config);
    return { snapshot, created: true, changed: true };
  });
  if (result.changed) notify([result.snapshot.id]);
  return { snapshot: result.snapshot, created: result.created };
}

// Saves new snapshots, skipping configured servers' own pages and, with
// skipSavedUrls, any URL that already has a snapshot. Returns those saved.
export async function addSnapshots(snapshots: Snapshot[], options: { skipSavedUrls?: boolean } = {}): Promise<Snapshot[]> {
  const [{ transaction }, config] = await Promise.all([db(), getConfig()]);
  const added: Snapshot[] = [];
  for (let start = 0; start < snapshots.length; start += batchSize) {
    await transaction(async tx => {
      for (const init of snapshots.slice(start, start + batchSize)) {
        if (isServerPage(init.url, config)) continue;
        if (options.skipSavedUrls && (await tx.select({ id: core_snapshot.id }).from(core_snapshot).where(eq(core_snapshot.url, init.url)).limit(1)).length) continue;
        const snapshot = withOwner(init, config);
        await writeSnapshot(tx, snapshot, config);
        added.push(snapshot);
      }
    });
  }
  if (added.length) notify(added.map(snapshot => snapshot.id));
  return added;
}

// Applies fn to each snapshot and saves what changed, in one transaction per
// batch. fn must be synchronous and must not call back into this module: the
// connection is busy until it returns. Returning an unchanged snapshot skips
// the write. Returns the saved snapshots (unchanged ones included).
export async function updateSnapshots(ids: string[], fn: (snapshot: Snapshot) => Snapshot): Promise<Snapshot[]> {
  const [{ transaction }, config] = await Promise.all([db(), getConfig()]);
  const changed: string[] = [];
  const saved: Snapshot[] = [];
  for (let start = 0; start < ids.length; start += batchSize) {
    await transaction(async tx => {
      for (const previous of await selectSnapshots(tx, inArray(core_snapshot.id, ids.slice(start, start + batchSize)))) {
        const updated = fn(structuredClone(previous));
        if (JSON.stringify(updated) === JSON.stringify(previous)) { saved.push(previous); continue; }
        const next = resetChangedCaptureUploads(previous, updated, config);
        await writeSnapshot(tx, next, config);
        changed.push(next.id);
        saved.push(next);
      }
    });
  }
  if (changed.length) notify(changed);
  return saved;
}

export async function updateSnapshot(id: string, fn: (snapshot: Snapshot) => Snapshot): Promise<Snapshot | null> {
  return (await updateSnapshots([id], fn))[0] ?? null;
}

// A recaptured file must be uploaded again: a delivery marked complete goes
// back to accepted for every server whose policy uploads that capture type.
function resetChangedCaptureUploads(previous: Snapshot, snapshot: Snapshot, config: ConfigState): Snapshot {
  if (!snapshot.remote_copies) return snapshot;
  const changed = (kind: CaptureKind) => snapshot[kind] && JSON.stringify(previous[kind]) !== JSON.stringify(snapshot[kind]);
  if (!captureKinds.some(changed)) return snapshot;
  const copies = Object.fromEntries(Object.entries(snapshot.remote_copies).map(([id, copy]) => {
    const policy = { ...defaultServerPolicy, ...config.server_policies[id] };
    const pending = (changed('viewport_screenshot') && policy.upload_viewport_screenshots_to_server)
      || (changed('screenshot') && policy.upload_screenshots_to_server)
      || (changed('mhtml') && policy.upload_mhtml_to_server)
      || (changed('singlefile') && policy.upload_singlefile_to_server);
    return [id, pending ? { ...copy, status: 'accepted' as const } : copy];
  }));
  return { ...snapshot, remote_copies: copies };
}

// Deletes snapshot records (their capture results, tags and receipts with
// them). Capture files are separate: see deleteSnapshotFiles.
export async function deleteSnapshots(ids: string[]): Promise<void> {
  if (!ids.length) return;
  const { transaction } = await db();
  for (let start = 0; start < ids.length; start += batchSize) {
    await transaction(tx => tx.delete(core_snapshot).where(inArray(core_snapshot.id, ids.slice(start, start + batchSize))));
  }
  notify(ids);
}

// Retention settings changed: recompute every delete_at, in batches. Runs
// in the background; until it finishes, retention may act on the old schedule
// for some rows, and always re-checks before deleting.
export async function refreshDeleteAt(): Promise<void> {
  await navigator.locks.request('archivebox-refresh-delete-at', async () => {
    const [{ transaction }, config] = await Promise.all([db(), getConfig()]);
    await walkSnapshots(undefined, async (batch) => {
      await transaction(async tx => {
        for (const snapshot of batch) {
          await tx.update(core_snapshot).set({ delete_at: snapshotDeleteAt(snapshot, config) }).where(eq(core_snapshot.id, snapshot.id));
          for (const kind of captureKinds) {
            if (!snapshot[kind]) continue;
            await tx.update(core_archiveresult).set({ delete_at: archiveResultDeleteAt(snapshot, kind, config) })
              .where(and(eq(core_archiveresult.snapshot_id, snapshot.id), eq(core_archiveresult.plugin, capturePlugins[kind])));
          }
        }
      });
    });
  });
}

// Writes snapshots exactly as given (owner included), replacing any with the
// same id. For restoring data and seeding test fixtures; normal saves go
// through addSnapshots/ensureSnapshot.
export async function putSnapshots(snapshots: Snapshot[]): Promise<void> {
  const [{ transaction }, config] = await Promise.all([db(), getConfig()]);
  for (let start = 0; start < snapshots.length; start += batchSize) {
    await transaction(async tx => {
      for (const snapshot of snapshots.slice(start, start + batchSize)) await writeSnapshot(tx, snapshot, config);
    });
  }
  notify(snapshots.map(snapshot => snapshot.id));
}

// Lets the extension's own DevTools console and the Playwright tests inspect
